class SoldeInsuffisantError(Exception):
    pass

class CompteBancaire:
    def __init__(self, titulaire, solde=0):
        if not isinstance(titulaire, str):
            raise ValueError("Le titulaire doit être une chaîne de caractères")
        if not isinstance(solde, (int, float)) or solde < 0:
            raise ValueError("Le solde doit être un nombre positif")
        self.titulaire = titulaire
        self.solde = solde

    def deposer(self, montant):
        if not isinstance(montant, (int, float)):
            raise ValueError("Le montant doit être un nombre")
        if montant < 0:
            raise ValueError("Le montant doit être positif")
        self.solde += montant

    def retirer(self, montant):
        if not isinstance(montant, (int, float)):
            raise ValueError("Le montant doit être un nombre")
        if montant < 0:
            raise ValueError("Le montant doit être positif")
        if montant > self.solde:
            raise SoldeInsuffisantError(f"Solde insuffisant : {self.solde} FCFA < {montant} FCFA")
        self.solde -= montant

    def afficher_solde(self):
        return self.solde
