import statistics

def calculer_statistiques(donnees):
    if not donnees:
        return {
            'moyenne_age': 0,
            'age_median': 0,
            'repartition_region': {},
            'repartition_genre': {'F': 0, 'M': 0}
        }

    ages = [d['age'] for d in donnees]
    regions = {}
    genres = {'F': 0, 'M': 0}

    for d in donnees:
        region = d['region']
        regions[region] = regions.get(region, 0) + 1
        genre = d['genre']
        if genre in genres:
            genres[genre] += 1
        else:
            genres[genre] = 1

    total = len(donnees)
    repartition_genre = {g: count/total for g, count in genres.items()}

    return {
        'moyenne_age': statistics.mean(ages),
        'age_median': statistics.median(ages),
        'repartition_region': regions,
        'repartition_genre': repartition_genre
    }
