class GestionnaireNotes:
    def __init__(self):
        self.notes = {}

    def ajouter_note(self, etudiant, note):
        if not isinstance(note, (int, float)):
            raise ValueError("La note doit être un nombre")
        if not 0 <= note <= 20:
            raise ValueError("La note doit être comprise entre 0 et 20")
        if etudiant not in self.notes:
            self.notes[etudiant] = []
        self.notes[etudiant].append(note)

    def calculer_moyenne(self, etudiant):
        if etudiant not in self.notes or not self.notes[etudiant]:
            return None
        return sum(self.notes[etudiant]) / len(self.notes[etudiant])

    def calculer_moyenne_classe(self):
        moyennes = [self.calculer_moyenne(e) for e in self.notes if self.notes[e]]
        if not moyennes:
            return None
        return sum(moyennes) / len(moyennes)

    def obtenir_classement(self):
        classement = []
        for etudiant, notes in self.notes.items():
            if notes:
                moyenne = self.calculer_moyenne(etudiant)
                classement.append((etudiant, moyenne))
        return sorted(classement, key=lambda x: x[1], reverse=True)
