import unittest

class TestGestionnaireNotes(unittest.TestCase):
    def setUp(self):
        self.gestionnaire = GestionnaireNotes()
        self.etudiants = ['Alice', 'Bob', 'Charlie']
        self.notes = {
            'Alice': [15, 18, 14],
            'Bob': [12, 11, 13],
            'Charlie': [16, 19, 17]
        }
        for etudiant, notes in self.notes.items():
            for note in notes:
                self.gestionnaire.ajouter_note(etudiant, note)

    def test_ajouter_note(self):
        self.gestionnaire.ajouter_note('Diana', 14)
        self.assertIn('Diana', self.gestionnaire.notes)
        self.assertEqual(self.gestionnaire.notes['Diana'], [14])

    def test_ajouter_note_note_invalide(self):
        with self.assertRaises(ValueError):
            self.gestionnaire.ajouter_note('Diana', 25)
        with self.assertRaises(ValueError):
            self.gestionnaire.ajouter_note('Diana', -5)
        with self.assertRaises(ValueError):
            self.gestionnaire.ajouter_note('Diana', 'A')

    def test_calculer_moyenne(self):
        self.assertEqual(self.gestionnaire.calculer_moyenne('Alice'), (15+18+14)/3)
        self.assertEqual(self.gestionnaire.calculer_moyenne('Bob'), (12+11+13)/3)
        self.assertEqual(self.gestionnaire.calculer_moyenne('Charlie'), (16+19+17)/3)

    def test_calculer_moyenne_etudiant_inexistant(self):
        self.assertIsNone(self.gestionnaire.calculer_moyenne('Diana'))

    def test_calculer_moyenne_classe(self):
        moyenne_attendu = ((15+18+14)/3 + (12+11+13)/3 + (16+19+17)/3) / 3
        self.assertEqual(self.gestionnaire.calculer_moyenne_classe(), moyenne_attendu)

    def test_calculer_moyenne_classe_vide(self):
        gestionnaire_vide = GestionnaireNotes()
        self.assertIsNone(gestionnaire_vide.calculer_moyenne_classe())

    def test_obtenir_classement(self):
        classement = self.gestionnaire.obtenir_classement()
        self.assertEqual(classement[0][0], 'Charlie')  # Meilleur
        self.assertEqual(classement[1][0], 'Alice')
        self.assertEqual(classement[2][0], 'Bob')
